const CACHE='waystep-v15';
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(['./','./index.html','./ai.html','./features.js?v=14','./cloud-config.js','./cloud-bundle.js','./style.css','./readability.css','./fonts/AtkinsonHyperlegibleNext.ttf','./app.js?v=14','./example-plan.js','./ai.js','./air-route.svg','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest'])));self.skipWaiting()});
self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith('waystep-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(fetch(e.request).then(r=>{if(r.ok){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html','./ai.html','./manifest-ai.webmanifest','./features.js?v=14','./cloud-config.js','./cloud-bundle.js'):Response.error()))))});
